import{_ as e,c as r,o as i,a3 as l}from"./chunks/framework.BurWKwwG.js";const _=JSON.parse('{"title":"搜索功能","description":"","frontmatter":{},"headers":[],"relativePath":"zh/3.2_search.md","filePath":"zh/3.2_search.md"}'),t={name:"zh/3.2_search.md"};function o(n,a,s,h,c,d){return i(),r("div",null,a[0]||(a[0]=[l('<h1 id="搜索功能" tabindex="-1">搜索功能 <a class="header-anchor" href="#搜索功能" aria-label="Permalink to “搜索功能”">​</a></h1><p>CBD3 提供多个入口进行生物标志物和相关数据的搜索。</p><h2 id="首页搜索" tabindex="-1">首页搜索 <a class="header-anchor" href="#首页搜索" aria-label="Permalink to “首页搜索”">​</a></h2><p>首页提供快速搜索框，用户可输入基因名称或关键词，直接跳转到对应的生物标志物或分析结果。</p><h2 id="biomarker-页面搜索" tabindex="-1">Biomarker 页面搜索 <a class="header-anchor" href="#biomarker-页面搜索" aria-label="Permalink to “Biomarker 页面搜索”">​</a></h2><p>Biomarker 页面（<code>/biomarker</code>）提供：</p><ul><li>关键词搜索框，支持按基因名称、描述等字段筛选</li><li>分页表格浏览全部生物标志物记录</li></ul><h2 id="高级搜索" tabindex="-1">高级搜索 <a class="header-anchor" href="#高级搜索" aria-label="Permalink to “高级搜索”">​</a></h2><p>Advanced Search 页面（<code>/search</code>）提供多条件组合搜索：</p><ul><li>支持按多个字段设置筛选条件</li><li>可保存常用搜索条件，方便下次使用</li></ul><h2 id="基因自动补全" tabindex="-1">基因自动补全 <a class="header-anchor" href="#基因自动补全" aria-label="Permalink to “基因自动补全”">​</a></h2><p>以下模块中的基因搜索框均支持自动补全功能：</p><ul><li>DEGs 分析（Original / By Celltype / Tumor vs Normal）</li><li>Trajectory 的 Interactive Pseudotime（Gene Expression 模式）</li><li>CellChat（Biomarker as Ligand / Receptor）</li><li>Network Sensitivity</li><li>Predictive Ability</li></ul><p>输入时自动触发后端搜索 API（300ms 防抖），从数据库中匹配基因名称并显示候选列表。</p><h2 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h2><h3 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h3><ul><li><strong>无结果</strong>：尝试更广泛的术语或检查拼写</li><li><strong>结果过多</strong>：添加更具体的过滤条件</li><li><strong>性能缓慢</strong>：减少搜索范围或添加过滤条件</li></ul>',17)]))}const p=e(t,[["render",o]]);export{_ as __pageData,p as default};
